import{_ as r,o as a,c as e,a2 as o}from"./chunks/framework.DDk04jjR.js";const c=JSON.parse('{"title":"Основи Fusion","description":"Знайомство з Autodesk Fusion 360 — параметричне моделювання та проєктування","frontmatter":{"layout":"page","title":"Основи Fusion","description":"Знайомство з Autodesk Fusion 360 — параметричне моделювання та проєктування"},"headers":[],"relativePath":"fusion-basics.md","filePath":"fusion-basics.md"}'),i={name:"fusion-basics.md"};function l(n,t,d,s,h,u){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="⚙️-основи-fusion-360" tabindex="-1">⚙️ Основи Fusion 360 <a class="header-anchor" href="#⚙️-основи-fusion-360" aria-label="Permalink to &quot;⚙️ Основи Fusion 360&quot;">​</a></h1><h2 id="що-таке-fusion-360" tabindex="-1">Що таке Fusion 360? <a class="header-anchor" href="#що-таке-fusion-360" aria-label="Permalink to &quot;Що таке Fusion 360?&quot;">​</a></h2><p><strong>Autodesk Fusion 360</strong> — це хмарна CAD/CAM/CAE-платформа для параметричного 3D-моделювання, інженерного аналізу та підготовки до виробництва. Безкоштовна для студентів та навчальних закладів.</p><blockquote><p>💡 Fusion 360 ідеально підходить для проєктування деталей, які потім будуть надруковані на 3D-принтері.</p></blockquote><hr><h2 id="інтерфеис-програми" tabindex="-1">Інтерфейс програми <a class="header-anchor" href="#інтерфеис-програми" aria-label="Permalink to &quot;Інтерфейс програми&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Елемент</th><th>Призначення</th></tr></thead><tbody><tr><td><strong>Browser</strong> (ліва панель)</td><td>Дерево побудови — список усіх операцій моделі</td></tr><tr><td><strong>Canvas</strong></td><td>Робочий простір для 3D-моделювання</td></tr><tr><td><strong>Toolbar</strong></td><td>Панель інструментів з основними командами</td></tr><tr><td><strong>Timeline</strong></td><td>Хронологія операцій внизу екрану</td></tr><tr><td><strong>ViewCube</strong></td><td>Навігаційний куб у правому верхньому куті</td></tr></tbody></table><hr><h2 id="основні-концепціі" tabindex="-1">Основні концепції <a class="header-anchor" href="#основні-концепціі" aria-label="Permalink to &quot;Основні концепції&quot;">​</a></h2><h3 id="параметричне-моделювання" tabindex="-1">Параметричне моделювання <a class="header-anchor" href="#параметричне-моделювання" aria-label="Permalink to &quot;Параметричне моделювання&quot;">​</a></h3><p>На відміну від Blender, у Fusion 360 ви працюєте з <strong>параметричними ескізами</strong>:</p><ol><li>Створюєте 2D-ескіз на площині</li><li>Задаєте точні розміри та обмеження (constraints)</li><li>Перетворюєте ескіз у 3D-тіло за допомогою операцій</li></ol><h3 id="типи-робочих-просторів" tabindex="-1">Типи робочих просторів <a class="header-anchor" href="#типи-робочих-просторів" aria-label="Permalink to &quot;Типи робочих просторів&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Простір</th><th>Для чого</th></tr></thead><tbody><tr><td><strong>Design</strong></td><td>Основне моделювання деталей</td></tr><tr><td><strong>Render</strong></td><td>Візуалізація та рендеринг</td></tr><tr><td><strong>Animation</strong></td><td>Анімація збірок</td></tr><tr><td><strong>Manufacture</strong></td><td>Підготовка до ЧПУ або 3D-друку</td></tr><tr><td><strong>Drawing</strong></td><td>Створення креслень</td></tr></tbody></table><hr><h2 id="створення-ескізу-sketch" tabindex="-1">Створення ескізу (Sketch) <a class="header-anchor" href="#створення-ескізу-sketch" aria-label="Permalink to &quot;Створення ескізу (Sketch)&quot;">​</a></h2><h3 id="початок-роботи" tabindex="-1">Початок роботи <a class="header-anchor" href="#початок-роботи" aria-label="Permalink to &quot;Початок роботи&quot;">​</a></h3><ol><li>Натисніть <strong>Create Sketch</strong> на панелі інструментів</li><li>Оберіть площину (XY, XZ або YZ)</li><li>Використовуйте інструменти малювання</li></ol><h3 id="основні-інструменти-ескізу" tabindex="-1">Основні інструменти ескізу <a class="header-anchor" href="#основні-інструменти-ескізу" aria-label="Permalink to &quot;Основні інструменти ескізу&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Інструмент</th><th>Опис</th></tr></thead><tbody><tr><td><strong>Line</strong> (L)</td><td>Пряма лінія</td></tr><tr><td><strong>Rectangle</strong> (R)</td><td>Прямокутник</td></tr><tr><td><strong>Circle</strong> (C)</td><td>Коло</td></tr><tr><td><strong>Arc</strong></td><td>Дуга</td></tr><tr><td><strong>Fillet</strong></td><td>Скруглення кута</td></tr><tr><td><strong>Trim</strong> (T)</td><td>Обрізка ліній</td></tr><tr><td><strong>Dimension</strong> (D)</td><td>Задати розмір</td></tr></tbody></table><h3 id="обмеження-constraints" tabindex="-1">Обмеження (Constraints) <a class="header-anchor" href="#обмеження-constraints" aria-label="Permalink to &quot;Обмеження (Constraints)&quot;">​</a></h3><ul><li><strong>Coincident</strong> — збіг точок</li><li><strong>Horizontal / Vertical</strong> — горизонтальність / вертикальність</li><li><strong>Parallel</strong> — паралельність</li><li><strong>Perpendicular</strong> — перпендикулярність</li><li><strong>Equal</strong> — рівність розмірів</li><li><strong>Tangent</strong> — дотичність</li></ul><hr><h2 id="основні-3d-операціі" tabindex="-1">Основні 3D-операції <a class="header-anchor" href="#основні-3d-операціі" aria-label="Permalink to &quot;Основні 3D-операції&quot;">​</a></h2><h3 id="extrude-видавлювання" tabindex="-1">Extrude (Видавлювання) <a class="header-anchor" href="#extrude-видавлювання" aria-label="Permalink to &quot;Extrude (Видавлювання)&quot;">​</a></h3><p>Перетворює 2D-ескіз у 3D-тіло, витягуючи його на задану висоту.</p><h3 id="revolve-обертання" tabindex="-1">Revolve (Обертання) <a class="header-anchor" href="#revolve-обертання" aria-label="Permalink to &quot;Revolve (Обертання)&quot;">​</a></h3><p>Створює тіло обертання навколо осі — ідеально для круглих деталей (вази, ручки).</p><h3 id="fillet-chamfer" tabindex="-1">Fillet / Chamfer <a class="header-anchor" href="#fillet-chamfer" aria-label="Permalink to &quot;Fillet / Chamfer&quot;">​</a></h3><ul><li><strong>Fillet</strong> — скруглення ребер</li><li><strong>Chamfer</strong> — зрізання ребер під кутом</li></ul><h3 id="hole" tabindex="-1">Hole <a class="header-anchor" href="#hole" aria-label="Permalink to &quot;Hole&quot;">​</a></h3><p>Створення точних отворів з різьбою або без.</p><h3 id="mirror-pattern" tabindex="-1">Mirror / Pattern <a class="header-anchor" href="#mirror-pattern" aria-label="Permalink to &quot;Mirror / Pattern&quot;">​</a></h3><ul><li><strong>Mirror</strong> — дзеркальне відображення</li><li><strong>Circular / Rectangular Pattern</strong> — масив копій</li></ul><hr><h2 id="першии-проєкт-підставка-для-телефону" tabindex="-1">Перший проєкт: підставка для телефону <a class="header-anchor" href="#першии-проєкт-підставка-для-телефону" aria-label="Permalink to &quot;Перший проєкт: підставка для телефону&quot;">​</a></h2><h3 id="крок-1-—-базовии-ескіз" tabindex="-1">Крок 1 — Базовий ескіз <a class="header-anchor" href="#крок-1-—-базовии-ескіз" aria-label="Permalink to &quot;Крок 1 — Базовий ескіз&quot;">​</a></h3><ol><li>Create Sketch → площина XY</li><li>Намалюйте прямокутник <strong>80 × 60 мм</strong></li><li>Закрийте ескіз (Finish Sketch)</li></ol><h3 id="крок-2-—-видавлювання" tabindex="-1">Крок 2 — Видавлювання <a class="header-anchor" href="#крок-2-—-видавлювання" aria-label="Permalink to &quot;Крок 2 — Видавлювання&quot;">​</a></h3><ol><li><strong>Extrude</strong> → висота <strong>10 мм</strong></li></ol><h3 id="крок-3-—-паз-для-телефону" tabindex="-1">Крок 3 — Паз для телефону <a class="header-anchor" href="#крок-3-—-паз-для-телефону" aria-label="Permalink to &quot;Крок 3 — Паз для телефону&quot;">​</a></h3><ol><li>Створіть новий ескіз на верхній грані</li><li>Прямокутник <strong>70 × 4 мм</strong> по центру</li><li>Extrude → <strong>-8 мм</strong> (вирізання вниз)</li></ol><h3 id="крок-4-—-скруглення" tabindex="-1">Крок 4 — Скруглення <a class="header-anchor" href="#крок-4-—-скруглення" aria-label="Permalink to &quot;Крок 4 — Скруглення&quot;">​</a></h3><ol><li>Виділіть зовнішні ребра</li><li><strong>Fillet</strong> → радіус <strong>3 мм</strong></li></ol><hr><h2 id="експорт-для-3d-друку" tabindex="-1">Експорт для 3D-друку <a class="header-anchor" href="#експорт-для-3d-друку" aria-label="Permalink to &quot;Експорт для 3D-друку&quot;">​</a></h2><ol><li>Правий клік на тіло в Browser → <strong>Save as STL</strong></li><li>Оберіть одиниці вимірювання (мм)</li><li>Задайте якість мережі (High для точності)</li><li>Збережіть файл для подальшого слайсингу</li></ol><hr><h2 id="корисні-гарячі-клавіші" tabindex="-1">Корисні гарячі клавіші <a class="header-anchor" href="#корисні-гарячі-клавіші" aria-label="Permalink to &quot;Корисні гарячі клавіші&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Дія</th><th>Клавіша</th></tr></thead><tbody><tr><td>Переміщення виду</td><td>Shift + СКМ</td></tr><tr><td>Обертання виду</td><td>СКМ</td></tr><tr><td>Масштабування</td><td>Колесо прокрутки</td></tr><tr><td>Пошук команди</td><td><strong>S</strong></td></tr><tr><td>Скасувати</td><td>Ctrl + Z</td></tr><tr><td>Виміряти</td><td><strong>I</strong> (Inspect → Measure)</td></tr></tbody></table><hr><h2 id="що-далі" tabindex="-1">Що далі? <a class="header-anchor" href="#що-далі" aria-label="Permalink to &quot;Що далі?&quot;">​</a></h2><ul><li>Вивчіть <strong>збірки (Assemblies)</strong> — з&#39;єднання кількох деталей</li><li>Опануйте <strong>параметричний дизайн</strong> — зміна розмірів через параметри</li><li>Спробуйте <strong>Render</strong> — фотореалістичну візуалізацію</li><li>Підготуйте модель до 3D-друку через <strong>Manufacture</strong></li></ul>',53)])])}const b=r(i,[["render",l]]);export{c as __pageData,b as default};
